    std::vector<int> count(n);
    int balance=0,minimum=0,start=0;
    for(int i=0;i<n;++i){std::cin>>count[i];balance+=count[i]-1;if(balance<minimum){minimum=balance;start=(i+1)%n;}}
    std::deque<int> waiting;
    long long energy=0;
    for(int position=0;position<n;++position){
        for(int cows=count[(start+position)%n];cows>0;--cows)waiting.push_back(position);
        const long long distance=position-waiting.front();waiting.pop_front();
        energy+=distance*distance;
    }
    std::cout<<energy<<'\n';return 0;
}
