#include <algorithm>
#include <cstdio>
#include <iostream>
#include <limits>
#include <vector>
int main(){
    std::freopen("cbarn2.in","r",stdin);
    std::freopen("cbarn2.out","w",stdout);
    std::ios::sync_with_stdio(false);std::cin.tie(nullptr);
    int n,k;if(!(std::cin>>n>>k))return 0;
    std::vector<long long> demand(n);for(auto& r:demand)std::cin>>r;
    // k==n is exact. k>n is an explicitly separate all-doors extension,
    // not a claim that more than n distinct physical doors can be chosen.
    if(k>=n){std::cout<<0<<'\n';return 0;}
    constexpr long long inf=std::numeric_limits<long long>::max()/4;
    long long answer=inf;
    for(int start=0;start<n;++start){
        std::vector<std::vector<long long>> cost(n,std::vector<long long>(n));
        for(int left=0;left<n;++left){
            long long total=0;
            for(int right=left;right<n;++right){total+=demand[(start+right)%n]*(right-left);cost[left][right]=total;}
        }
        std::vector<long long> previous(n+1,inf);previous[0]=0;
        for(int doors=1;doors<=k;++doors){
            std::vector<long long> current(n+1,inf);
            for(int rooms=doors;rooms<=n;++rooms)for(int last=doors-1;last<rooms;++last){
                if(previous[last]!=inf)current[rooms]=std::min(current[rooms],previous[last]+cost[last][rooms-1]);
            }
            previous.swap(current);
        }
        answer=std::min(answer,previous[n]);
    }
    std::cout<<answer<<'\n';return 0;
}
