    long long a,b;int n,m;if(!(std::cin>>a>>b>>n>>m))return 0;
    std::vector<long long> x{0,a},y{0,b};
    for(int i=0;i<n;++i){long long coordinate;std::cin>>coordinate;x.push_back(coordinate);}
    for(int i=0;i<m;++i){long long coordinate;std::cin>>coordinate;y.push_back(coordinate);}
    std::sort(x.begin(),x.end());std::sort(y.begin(),y.end());
    std::vector<long long> width,height;
    for(std::size_t i=1;i<x.size();++i)width.push_back(x[i]-x[i-1]);
    for(std::size_t i=1;i<y.size();++i)height.push_back(y[i]-y[i-1]);
    std::sort(width.begin(),width.end());std::sort(height.begin(),height.end());
    const int columns=n+1,rows=m+1;
    int i=0,j=0;long long answer=0;
    while(i<columns||j<rows){
        if(j==rows||(i<columns&&width[i]<=height[j])){
            const long long accepted=(i==0||j==0)?rows-1:rows-j;
            answer+=width[i]*accepted;++i;
        }else{
            const long long accepted=(i==0||j==0)?columns-1:columns-i;
            answer+=height[j]*accepted;++j;
        }
    }
    std::cout<<answer<<'\n';return 0;
}
